const VALID_STATUSES = new Set(['pass', 'fail', 'reject', 'missing', 'timeout', 'crash', 'skip']);

function isRecord(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function ratio(numerator, denominator) {
  return denominator === 0 ? null : numerator / denominator;
}

function roundMetric(value) {
  return value === null ? null : Number(value.toFixed(6));
}

function normalizeStatus(status) {
  if (typeof status !== 'string' || !VALID_STATUSES.has(status)) {
    throw new TypeError(`Unknown reliability trial status: ${String(status)}`);
  }
  return status;
}

function trialSucceeded(trial, expectedOutcome) {
  if (trial.status === 'pass') return true;
  if (trial.status === 'reject') return expectedOutcome === 'negative';
  return false;
}

function anchorViolation(trial, anchor) {
  if (anchor === 'positive') return trial.status !== 'pass';
  if (anchor === 'negative') return trial.status !== 'reject';
  return false;
}

/**
 * Aggregate deterministic, repeated reliability trials.
 *
 * A case is complete only when it contains exactly k recorded trials and none of
 * those trials is missing, timed out, crashed, or skipped. Incomplete cases are
 * retained in the report but excluded from pass^k and pass@k denominators.
 */
export function aggregateReliability(input) {
  if (!isRecord(input)) throw new TypeError('Reliability input must be an object');
  const source = isRecord(input.fixture) ? input.fixture : input;
  const design = isRecord(source.design) ? source.design : {};
  const cases = Array.isArray(source.cases) ? source.cases : [];
  const k = input.k ?? design.k;
  const minCases = input.minCases ?? design.minCases;
  const flakeThreshold = input.flakeThreshold ?? design.flakeThreshold ?? 0;
  if (!Number.isInteger(k) || k < 1) throw new TypeError('k must be a positive integer');
  if (!Number.isInteger(minCases) || minCases < 1) throw new TypeError('minCases must be a positive integer');
  if (!Number.isFinite(flakeThreshold) || flakeThreshold < 0 || flakeThreshold > 1) {
    throw new TypeError('flakeThreshold must be between 0 and 1');
  }

  const statusCounts = { pass: 0, fail: 0, reject: 0, missing: 0, timeout: 0, crash: 0, skip: 0 };
  const incompleteReasons = { missing: 0, timeout: 0, crash: 0, skip: 0 };
  const perCase = [];
  let completeCases = 0;
  let allTrialsPassed = 0;
  let anyTrialPassed = 0;
  let validTrials = 0;
  let successfulTrials = 0;
  let flakeCases = 0;
  let initialFailures = 0;
  let anchorViolations = 0;
  const safetySkipCases = [];
  const safetyFlakeCases = [];

  for (const item of cases) {
    if (!isRecord(item)) throw new TypeError('Each reliability case must be an object');
    const id = typeof item.id === 'string' ? item.id : '';
    const anchor = item.anchor === 'positive' || item.anchor === 'negative' ? item.anchor : null;
    const safety = item.safety === true;
    const trials = Array.isArray(item.trials) ? item.trials : [];
    const statuses = trials.map((trial) => normalizeStatus(isRecord(trial) ? trial.status : trial));
    for (const status of statuses) statusCounts[status] += 1;

    const incomplete = statuses.length !== k || statuses.some((status) => ['missing', 'timeout', 'crash', 'skip'].includes(status));
    const incompleteStatusCounts = { missing: 0, timeout: 0, crash: 0, skip: 0 };
    for (const status of statuses) {
      if (Object.hasOwn(incompleteStatusCounts, status)) incompleteStatusCounts[status] += 1;
    }
    for (const reason of Object.keys(incompleteStatusCounts)) {
      if (incompleteStatusCounts[reason] > 0) incompleteReasons[reason] += 1;
    }

    const expectedOutcome = anchor ?? (item.expectedOutcome === 'negative' ? 'negative' : 'positive');
    const successes = trials.filter((trial, index) => trialSucceeded({ status: statuses[index] }, expectedOutcome)).length;
    const firstFailed = statuses.length > 0 && (statuses[0] === 'fail' || (expectedOutcome === 'positive' && statuses[0] !== 'pass'));
    const laterSucceeded = statuses.length > 1 && trials.slice(1).some((trial, index) => trialSucceeded({ status: statuses[index + 1] }, expectedOutcome));
    const flaky = firstFailed && laterSucceeded;
    if (firstFailed) initialFailures += 1;
    if (flaky) flakeCases += 1;

    let violated = false;
    if (anchor) {
      violated = statuses.some((status) => anchorViolation({ status }, anchor));
      if (violated) anchorViolations += 1;
    }
    const skipped = statuses.includes('skip');
    if (safety && skipped) safetySkipCases.push(id);
    if (safety && flaky) safetyFlakeCases.push(id);

    if (!incomplete) {
      completeCases += 1;
      validTrials += trials.length;
      successfulTrials += successes;
      if (successes === trials.length) allTrialsPassed += 1;
      if (successes > 0) anyTrialPassed += 1;
    }

    perCase.push({
      id,
      anchor,
      safety,
      complete: !incomplete,
      trialCount: trials.length,
      trialStatuses: statuses,
      trialSuccesses: successes,
      incompleteReasons: incompleteStatusCounts,
      firstTrialFailed: firstFailed,
      flaky,
      anchorViolation: violated,
    });
  }

  const incompleteCases = perCase.filter((item) => !item.complete).length;
  const passAtK = roundMetric(ratio(allTrialsPassed, completeCases));
  const passAt1 = roundMetric(ratio(anyTrialPassed, completeCases));
  const trialSuccessRate = roundMetric(ratio(successfulTrials, validTrials));
  const flakeRate = roundMetric(ratio(flakeCases, completeCases));
  const reasons = [];
  if (completeCases < minCases) reasons.push(`complete cases ${completeCases} < required ${minCases}`);
  if (anchorViolations > 0) reasons.push(`${anchorViolations} anchor violation(s)`);
  if (safetySkipCases.length > 0) reasons.push(`${safetySkipCases.length} safety case(s) skipped`);
  if (safetyFlakeCases.length > 0) reasons.push(`${safetyFlakeCases.length} safety case(s) flaked`);
  if (flakeRate !== null && flakeRate > flakeThreshold) reasons.push(`flake ${flakeRate} > threshold ${flakeThreshold}`);
  const gate = completeCases < minCases ? 'insufficient-sample' : reasons.length === 0 ? 'pass' : 'fail';

  return {
    oracle: {
      kind: source.oracle?.kind === 'deterministic' ? 'deterministic' : 'deterministic',
      fixture: source.oracle?.fixture ?? null,
      realProviderClaim: false,
      humanClaim: false,
      generalizationClaim: false,
    },
    design: { k, minCases, flakeThreshold },
    denominators: {
      rawCases: cases.length,
      completeCases,
      incompleteCases,
      validTrials,
      allTrialsRecorded: statusCounts.pass + statusCounts.fail + statusCounts.reject + statusCounts.missing + statusCounts.timeout + statusCounts.crash + statusCounts.skip,
    },
    passAtK: {
      value: passAtK,
      numerator: allTrialsPassed,
      denominator: completeCases,
    },
    passAt1: {
      value: passAt1,
      numerator: anyTrialPassed,
      denominator: completeCases,
    },
    trialSuccessRate: {
      value: trialSuccessRate,
      numerator: successfulTrials,
      denominator: validTrials,
    },
    flake: {
      value: flakeRate,
      numerator: flakeCases,
      denominator: completeCases,
      threshold: flakeThreshold,
      cases: perCase.filter((item) => item.flaky).map((item) => item.id),
    },
    incomplete: {
      cases: incompleteCases,
      reasons: incompleteReasons,
      caseIds: perCase.filter((item) => !item.complete).map((item) => item.id),
    },
    statusCounts,
    initialFailures,
    anchors: {
      violations: anchorViolations,
      violatingCaseIds: perCase.filter((item) => item.anchorViolation).map((item) => item.id),
    },
    safety: {
      skipCases: safetySkipCases,
      flakeCases: safetyFlakeCases,
    },
    gate,
    reasons,
    cases: perCase,
  };
}

export default aggregateReliability;

export type ReliabilityTrialStatus =
  | 'pass'
  | 'fail'
  | 'reject'
  | 'missing'
  | 'timeout'
  | 'crash'
  | 'skip';

export interface ReliabilityTrial {
  status: ReliabilityTrialStatus;
}

export interface ReliabilityCase {
  id: string;
  anchor?: 'positive' | 'negative';
  expectedOutcome?: 'positive' | 'negative';
  safety?: boolean;
  trials: ReliabilityTrial[];
}

export interface ReliabilityFixture {
  oracle?: {
    kind?: 'deterministic';
    fixture?: string | null;
  };
  design?: {
    k?: number;
    minCases?: number;
    flakeThreshold?: number;
  };
  cases: ReliabilityCase[];
}

export interface ReliabilityMetric {
  value: number | null;
  numerator: number;
  denominator: number;
}

export interface ReliabilityAggregation {
  oracle: {
    kind: 'deterministic';
    fixture: string | null;
    realProviderClaim: false;
    humanClaim: false;
    generalizationClaim: false;
  };
  design: { k: number; minCases: number; flakeThreshold: number };
  denominators: {
    rawCases: number;
    completeCases: number;
    incompleteCases: number;
    validTrials: number;
    allTrialsRecorded: number;
  };
  passAtK: ReliabilityMetric;
  passAt1: ReliabilityMetric;
  trialSuccessRate: ReliabilityMetric;
  flake: ReliabilityMetric & { threshold: number; cases: string[] };
  incomplete: {
    cases: number;
    reasons: Record<'missing' | 'timeout' | 'crash' | 'skip', number>;
    caseIds: string[];
  };
  statusCounts: Record<ReliabilityTrialStatus, number>;
  initialFailures: number;
  anchors: { violations: number; violatingCaseIds: string[] };
  safety: { skipCases: string[]; flakeCases: string[] };
  gate: 'pass' | 'fail' | 'insufficient-sample';
  reasons: string[];
  cases: Array<{
    id: string;
    anchor: 'positive' | 'negative' | null;
    safety: boolean;
    complete: boolean;
    trialCount: number;
    trialStatuses: ReliabilityTrialStatus[];
    trialSuccesses: number;
    incompleteReasons: Record<'missing' | 'timeout' | 'crash' | 'skip', number>;
    firstTrialFailed: boolean;
    flaky: boolean;
    anchorViolation: boolean;
  }>;
}

export function aggregateReliability(
  input: ReliabilityFixture | (ReliabilityFixture & { k?: number; minCases?: number; flakeThreshold?: number }),
): ReliabilityAggregation;

export default aggregateReliability;

