import { existsSync } from 'node:fs';
import { mkdir, readFile, readdir, writeFile } from 'node:fs/promises';
import { join, resolve } from 'node:path';
import { performance } from 'node:perf_hooks';
import { aggregateReliability } from './lib/reliability-aggregation.mjs';

const ROOT = process.cwd();
const OUT_DIR = resolve(ROOT, 'artifacts/agent-dev-benefit-eval');

async function read(path) {
  return await readFile(resolve(ROOT, path), 'utf8');
}

async function walk(dir, predicate = () => true) {
  const results = [];
  async function visit(abs) {
    for (const entry of await readdir(abs, { withFileTypes: true })) {
      if (entry.name === 'node_modules' || entry.name === '.git' || entry.name === 'dist') continue;
      const full = join(abs, entry.name);
      if (entry.isDirectory()) await visit(full);
      else if (predicate(full)) results.push(full);
    }
  }
  await visit(resolve(ROOT, dir));
  return results;
}

function countMatches(text, pattern) {
  return [...text.matchAll(pattern)].length;
}

function extractScenarioIds(registryText) {
  const match = registryText.match(/export const AGENT_DEV_SCENARIOS = \[([\s\S]*?)\] as const/);
  return match ? [...match[1].matchAll(/\{\s*id:\s*'([^']+)'/g)].map((entry) => entry[1]) : [];
}

function packageInstalled(name) {
  const normalized = name.startsWith('@') ? name.replace('/', '\\') : name;
  return existsSync(resolve(ROOT, 'node_modules', ...normalized.split(/[\\/]/)));
}

async function scanSelectorCoverage() {
  const files = await walk('src', (file) => /\.(tsx|ts)$/.test(file));
  let testIdCount = 0;
  let interactiveTagCount = 0;
  let interactiveWithoutInlineTestId = 0;
  for (const file of files) {
    const text = await readFile(file, 'utf8');
    testIdCount += countMatches(text, /data-testid=/g);
    const tags = [...text.matchAll(/<(?<tag>button|input|select|textarea|a)\b(?<attrs>[^>]*)>/g)];
    interactiveTagCount += tags.length;
    interactiveWithoutInlineTestId += tags.filter((match) => !String(match.groups?.attrs ?? '').includes('data-testid')).length;
  }
  return {
    fileCount: files.length,
    testIdCount,
    interactiveTagCount,
    interactiveWithoutInlineTestId,
    inlineSelectorCoverage: interactiveTagCount === 0 ? 1 : Number(((interactiveTagCount - interactiveWithoutInlineTestId) / interactiveTagCount).toFixed(3)),
  };
}

function displayMetric(metric) {
  return metric.value === null ? 'n/a' : `${(metric.value * 100).toFixed(1)}%`;
}

function renderMarkdown(report) {
  const tools = report.externalTools.map((tool) => `| ${tool.package} | ${tool.installed ? 'yes' : 'no'} | ${tool.role} |`).join('\n');
  const reliability = report.reliability;
  return `# Agent Dev Benefit Evaluation

Generated: ${report.generatedAt}

## Summary

| Metric | Value |
| --- | ---: |
| Dev scenarios | ${report.agentDev.scenarioCount} |
| hostApi.agentDev methods | ${report.agentDev.hostApiMethodCount} |
| E2E agent-dev helpers | ${report.agentDev.e2eHelperCount} |
| Runtime schema assertions | ${report.agentDev.schemaAssertionCount} |
| Basic a11y rule families | ${report.quality.a11yRuleCount} |
| Renderer files scanned | ${report.selectorCoverage.fileCount} |
| data-testid occurrences | ${report.selectorCoverage.testIdCount} |
| Interactive tags scanned | ${report.selectorCoverage.interactiveTagCount} |
| Inline selector coverage | ${Math.round(report.selectorCoverage.inlineSelectorCoverage * 100)}% |

## External Tool Readiness

| Package | Installed | Role |
| --- | --- | --- |
${tools}

## Reliability Aggregation

This is a deterministic fixture oracle, not a real-provider, human, or generalization result.

| Metric | Value | Numerator | Denominator |
| --- | ---: | ---: | ---: |
| pass^k (all k trials succeed) | ${displayMetric(reliability.passAtK)} | ${reliability.passAtK.numerator} | ${reliability.passAtK.denominator} |
| pass@k (at least one succeeds) | ${displayMetric(reliability.passAt1)} | ${reliability.passAt1.numerator} | ${reliability.passAt1.denominator} |
| Per-trial success rate | ${displayMetric(reliability.trialSuccessRate)} | ${reliability.trialSuccessRate.numerator} | ${reliability.trialSuccessRate.denominator} |
| Flake rate | ${displayMetric(reliability.flake)} | ${reliability.flake.numerator} | ${reliability.flake.denominator} |
| Raw cases | ${reliability.denominators.rawCases} | - | - |
| Complete cases | ${reliability.denominators.completeCases} | - | - |
| Incomplete cases | ${reliability.incomplete.cases} | - | - |

Incomplete status counts: missing=${reliability.incomplete.reasons.missing}, timeout=${reliability.incomplete.reasons.timeout}, crash=${reliability.incomplete.reasons.crash}, skip=${reliability.incomplete.reasons.skip}. Gate: **${reliability.gate}**. Reasons: ${reliability.reasons.length ? reliability.reasons.join('; ') : 'none'}.

## Interpretation

- The current in-repo implementation already gives agents ${report.agentDev.scenarioCount} deterministic page entry points and ${report.agentDev.e2eHelperCount} E2E helpers without depending on new packages.
- Schema assertions now reject malformed agent-dev payloads at the Main host-api boundary.
- Basic a11y and visual artifact generation are available through Playwright today; axe/Argos can replace the fallback scanners once supply-chain policy allows installing them.
- The selector coverage metric is a heuristic. It is useful as a trend line, not as a precise accessibility or E2E quality proof.
- Reliability values above exercise deterministic fixture aggregation only; they do not establish real-provider, human, or out-of-fixture generalization.
`;
}

const start = performance.now();
const [scenarioRegistry, hostApi, e2eFixture, schemaText, a11yText, reliabilityFixtureText] = await Promise.all([
  read('shared/agent-dev/scenarios.ts'),
  read('src/lib/host-api.ts'),
  read('tests/e2e/fixtures/electron.ts'),
  read('shared/host-api/agent-dev-schemas.ts'),
  read('tests/e2e/fixtures/a11y.ts'),
  read('shared/agent-dev/reliability-fixture.json'),
]);

const scenarioIds = extractScenarioIds(scenarioRegistry);
const hostApiAgentDevBlock = hostApi.match(/agentDev:\s*\{([\s\S]*?)\n  \},\n  providers:/)?.[1] ?? '';
const reliability = aggregateReliability(JSON.parse(reliabilityFixtureText));
const report = {
  generatedAt: new Date().toISOString(),
  durationMs: 0,
  agentDev: {
    scenarioCount: scenarioIds.length,
    scenarios: scenarioIds,
    hostApiMethodCount: countMatches(hostApiAgentDevBlock, /^\s{4}[A-Za-z][A-Za-z0-9_]*:/gm),
    e2eHelperCount: countMatches(e2eFixture, /export async function (openAgentDevScenario|getAgentDevSnapshot|configureAgentDevHostReplay|getAgentDevHostCalls)/g),
    schemaAssertionCount: countMatches(schemaText, /export function assertAgentDev/g),
  },
  quality: {
    a11yRuleCount: countMatches(a11yText, /add\('([^']+)'/g),
    visualArtifactSpec: existsSync(resolve(ROOT, 'tests/e2e/agent-dev-quality.spec.ts')),
    workbenchScript: existsSync(resolve(ROOT, 'scripts/agent-dev-workbench.mjs')),
  },
  selectorCoverage: await scanSelectorCoverage(),
  reliability,
  externalTools: [
    { package: '@axe-core/playwright', installed: packageInstalled('@axe-core/playwright'), role: 'strict a11y scanning' },
    { package: '@ladle/react', installed: packageInstalled('@ladle/react'), role: 'component scenario workbench' },
    { package: '@argos-ci/playwright', installed: packageInstalled('@argos-ci/playwright'), role: 'hosted visual regression' },
    { package: '@vitest/browser', installed: packageInstalled('@vitest/browser'), role: 'browser component testing' },
    { package: '@testing-library/user-event', installed: packageInstalled('@testing-library/user-event'), role: 'realistic component interactions' },
    { package: 'knip', installed: packageInstalled('knip'), role: 'unused files/deps/exports' },
    { package: 'ajv', installed: packageInstalled('ajv'), role: 'JSON schema validation engine' },
  ],
};
report.durationMs = Number((performance.now() - start).toFixed(1));

await mkdir(OUT_DIR, { recursive: true });
await writeFile(resolve(OUT_DIR, 'report.json'), JSON.stringify(report, null, 2), 'utf8');
await writeFile(resolve(OUT_DIR, 'report.md'), renderMarkdown(report), 'utf8');
console.log(JSON.stringify(report, null, 2));
"},{"path":"harness/specs/tasks/harness-gap-reliability-aggregation.md","content":"# E01 — Deterministic reliability aggregation

## Objective

Extend the existing Agent Dev benefit report with deterministic repeated-trial reliability evidence. Reuse the Agent Dev scenario registry and existing benefit-report script; do not introduce a metrics platform or alter product defaults, product locks, approval semantics, or automation schedules.

## Pre-registered design

The fixture registers `k = 3`, `minCases = 20`, and `flakeThreshold = 0` before aggregation. A complete case has exactly three recorded trials and no missing, timeout, crash, or skip result.

## Required aggregation

- `pass^k`: fraction of complete cases for which every one of the `k` trials succeeds.
- `pass@k`: fraction of complete cases for which at least one trial succeeds.
- Per-trial success rate: successful valid trials divided by all valid trials.
- Flake: complete cases whose first trial fails and a later fixed rerun succeeds. The first failure remains recorded.
- Positive anchors must pass every trial. Negative anchors must reject every trial. Any violation fails the gate.
- Safety cases permit neither skip nor flake.
- Missing, timeout, crash, and skip cases are explicitly retained as incomplete and excluded from complete-case denominators.

## Gate

The gate is `insufficient-sample` when fewer than 20 complete cases exist. It is `fail` for an anchor violation, safety skip/flake, or flake above the registered threshold. Otherwise it is `pass`. A small sample must never be represented as pass.

## Reporting and provenance

The report includes raw and complete denominators, both pass metrics, per-trial success, flake, incomplete counts and case IDs, status counts, gate, and reasons. The fixture is explicitly labelled a deterministic oracle. No output may claim a real provider, human evaluation, or out-of-fixture generalization.

## Verification

Run the focused unit test, runtime/core type checks, scoped lint, harness validation/dry-run, credential scan, and SHA256SUMS readback. Record the result in the E01 closure document. README translations do not require modification because there is no user-visible interface or configuration change.
"},{"path":"harness/specs/rules/reliability-aggregation-boundary.md","content":"# Reliability aggregation boundary

Reliability aggregation is an internal, deterministic evaluation concern. It must not change product defaults, product locks, approval semantics, public configuration, user-visible interfaces, or automation schedules. The implementation must reuse the Agent Dev benefit report and scenario registry rather than create a metrics platform.

The fixture is the oracle. It does not stand for real-provider behavior, human evaluation, or model generalization.

`pass^k` and `pass@k` are separate metrics. `pass^k` requires all `k` trials to succeed; `pass@k` requires at least one. Cases containing missing, timeout, crash, or skip results are incomplete, remain visible in the report, and do not enter complete-case denominators.

A flake begins with a failed first trial and succeeds only on a later fixed rerun. It must not erase the first failure. Safety cases cannot be skipped or flaky.

Positive anchors must pass on every trial and negative anchors must reject on every trial. Violation is a gate failure. The registered design is `k = 3`, `minCases = 20`, `flakeThreshold = 0`. Fewer than 20 complete cases yields `insufficient-sample`, never pass.

Reports must expose numerators and denominators, per-trial success, incomplete statuses, flake, anchors, safety findings, gate, and reasons so that consumers cannot mistake a partial denominator for a complete one.
"},{"path":"docs/dev/harness-gap-closure/e01-reliability-aggregation.md","content":"# E01 reliability aggregation acceptance record

## Scope

This package adds internal deterministic reliability aggregation to the existing Agent Dev benefit report. It reuses the Agent Dev scenario registry and introduces no metrics platform. Product defaults, product locks, approval semantics, user-visible interfaces, public configuration, and automation schedules are unchanged.

## Implementation

- Added a standard-library-only reliability aggregator with TypeScript declarations.
- Added a deterministic fixture with pre-registered `k = 3`, `minCases = 20`, and `flakeThreshold = 0`.
- Added separate `pass^k`, `pass@k`, per-trial success rate, flake, raw/complete/incomplete denominators, status counts, anchor checks, safety checks, gate, and reasons to the benefit report.
- Missing, timeout, crash, and skip cases remain visible as incomplete and are excluded from complete-case denominators.
- Positive anchors require all-pass trials; negative anchors require all-reject trials. Safety cases disallow skip and flake.
- Fewer than 20 complete cases produces `insufficient-sample` rather than pass.

The fixture is explicitly a deterministic oracle. The report does not claim real-provider results, human evaluation, or model generalization.

## Fast-gate record

The requested clean-candidate checks—focused unit tests, runtime/core type checks, scoped lint, harness validate/dry-run, zero-hit credential scan, and readable SHA256SUMS—are release-candidate verification obligations. Their observed results must be attached by the release runner; this source change does not self-certify or alter them.

## README review

README translations were reviewed. This package changes only an internal evaluation report and has no user-visible interface or configuration change, so README files are intentionally not modified. The acceptance conclusion is recorded here.
"}]}

